const input = $input.item.json || {};

const parseInteger = (value, fallback) => {
  const parsed = parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const firstString = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
};

const normalizeUrl = (value) => {
  const original = String(value ?? '').trim();
  if (!original) {
    throw new Error('Missing required input field url');
  }

  let url = original
    .replace(/[\u0000-\u001F\u007F]/g, '')
    .trim();

  // Accept angle-bracketed URLs copied from chat/Slack/Markdown.
  const angleMatch = url.match(/^<(.+)>$/);
  if (angleMatch) {
    url = angleMatch[1].trim();
  }

  // Accept an already-built Jina Reader URL, but normalize it back to the target URL.
  url = url.replace(/^https?:\/\/r\.jina\.ai\//i, '').trim();

  // Match the working Brave workflow pattern: keep the target URL as a string and
  // build the Reader URL as https://r.jina.ai/${url}. Avoid new URL(...), which is
  // unnecessary here and previously failed inside n8n Code-node handling.
  if (url.startsWith('//')) {
    url = `https:${url}`;
  }

  // Fix accidental single-slash protocol forms like https:/example.com/page.
  url = url.replace(/^(https?:)\/(?!\/)/i, '$1//');

  // Treat bare hostnames as HTTPS URLs.
  if (!/^https?:\/\//i.test(url)) {
    if (!/^[a-z0-9.-]+\.[a-z]{2,}([/:?#]|$)/i.test(url)) {
      throw new Error('Invalid URL input - expected HTTP URL, HTTPS URL, protocol-relative URL, or bare hostname');
    }
    url = `https://${url}`;
  }

  if (!/^https?:\/\/[^\s]+/i.test(url)) {
    throw new Error('Invalid URL input - expected HTTP or HTTPS URL');
  }

  const hostname = url.replace(/^https?:\/\//i, '').split(/[/?#]/)[0];
  if (!hostname || hostname.includes(' ') || !hostname.includes('.')) {
    throw new Error('Invalid URL input - hostname is missing or malformed');
  }

  return url;
};

const url = normalizeUrl(firstString(input.url, input.targetUrl, input.sourceUrl, input.href, input.link));
const maxContentChars = clamp(parseInteger(input.maxContentChars ?? input.max_content_chars, 6000), 1000, 200000);
const requestTimeoutMs = clamp(parseInteger(input.requestTimeoutMs ?? input.request_timeout_ms, 60000), 1000, 300000);

const rateLimitMaxRequests = clamp(parseInteger(input.rateLimitMaxRequests ?? input.rate_limit_max_requests, 20), 1, 1000);
const rateLimitWindowSeconds = clamp(parseInteger(input.rateLimitWindowSeconds ?? input.rate_limit_window_seconds, 60), 1, 3600);
const rateLimitSleepBufferSeconds = clamp(parseInteger(input.rateLimitSleepBufferSeconds ?? input.rate_limit_sleep_buffer_seconds, 5), 0, 3600);
const redisRateLimitKey = firstString(
  input.redisRateLimitKey,
  input.redis_rate_limit_key,
  input.rateLimitKey,
  input.rate_limit_key,
) || 'jina_reader:free:rpm';

// maxAttempts is the total number of Reader fetch attempts, not additional retries.
// The first HTTP fetch is attempt 1. Default is 3 total attempts.
const maxAttempts = clamp(parseInteger(
  input.maxAttempts ??
  input.max_attempts ??
  input.retryMaxAttempts ??
  input.retry_max_attempts ??
  input.retryCount ??
  input.retry_count ??
  input.retries,
  3
), 1, 20);

return {
  json: {
    url,
    readerUrl: `https://r.jina.ai/${url}`,
    maxContentChars,
    requestTimeoutMs,
    provider: 'jina_reader',
    requestedAt: new Date().toISOString(),
    request: {
      url,
      maxContentChars,
      requestTimeoutMs,
      redisRateLimitKey,
      rateLimitMaxRequests,
      rateLimitWindowSeconds,
      rateLimitSleepBufferSeconds,
      maxAttempts
    },
    retry: {
      enabled: maxAttempts > 1,
      provider: 'workflow_loop',
      strategy: 'reader_http_error_retry_total_attempts_first_fetch_is_attempt_1',
      maxAttempts,
      currentAttempt: 1,
      attemptsMade: 0,
      remainingAttempts: maxAttempts - 1,
      errors: []
    },
    rateLimit: {
      enabled: true,
      provider: 'redis',
      redisKey: redisRateLimitKey,
      limit: rateLimitMaxRequests,
      windowSeconds: rateLimitWindowSeconds,
      sleepBufferSeconds: rateLimitSleepBufferSeconds,
      strategy: 'simple_counter_increment_before_request_reset_ttl_60s'
    }
  }
};

let attemptState = {};
try {
  attemptState = $('Prepare Attempt State').item.json || {};
} catch (error) {
  attemptState = {};
}

if (!attemptState.url) {
  try {
    attemptState = $('Normalize Input').first().json || {};
  } catch (error) {
    attemptState = {};
  }
}

const redisOutput = $input.item.json || {};
const redisKey = attemptState.rateLimit?.redisKey || attemptState.request?.redisRateLimitKey || 'jina_reader:free:rpm';

const numericFrom = (value) => {
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : null;
};

let counter = numericFrom(redisOutput[redisKey]);
if (counter === null) counter = numericFrom(redisOutput.value);
if (counter === null) counter = numericFrom(redisOutput.counter);
if (counter === null) counter = numericFrom(redisOutput.data);
if (counter === null) counter = numericFrom(redisOutput.result);
if (counter === null) {
  for (const value of Object.values(redisOutput)) {
    const parsed = numericFrom(value);
    if (parsed !== null) {
      counter = parsed;
      break;
    }
  }
}
if (counter === null) counter = 0;

const limit = attemptState.rateLimit?.limit ?? attemptState.request?.rateLimitMaxRequests ?? 20;
const windowSeconds = attemptState.rateLimit?.windowSeconds ?? attemptState.request?.rateLimitWindowSeconds ?? 60;
const sleepBufferSeconds = attemptState.rateLimit?.sleepBufferSeconds ?? attemptState.request?.rateLimitSleepBufferSeconds ?? 5;
const remainingTtlSeconds = windowSeconds;
const waitSeconds = remainingTtlSeconds + sleepBufferSeconds;
const allowed = counter <= limit;

return {
  json: {
    ...attemptState,
    rateLimit: {
      ...(attemptState.rateLimit || {}),
      enabled: true,
      provider: 'redis',
      redisKey,
      limit,
      windowSeconds,
      sleepBufferSeconds,
      counter,
      allowed,
      hit: !allowed,
      remainingTtlSeconds,
      waitSeconds,
      checkedAt: new Date().toISOString(),
      note: allowed
        ? 'Counter is within the configured free Jina Reader limit.'
        : 'Counter exceeded the configured limit. Wait remaining TTL plus buffer, then increment and check again.'
    }
  }
};

let source = {};
try {
  source = $('Attach Rate Limit State').item.json || {};
} catch (error) {
  source = $('Attach Rate Limit State').first().json || {};
}

const response = $input.item.json;

let content = '';
if (typeof response === 'string') {
  content = response;
} else if (typeof response?.data === 'string') {
  content = response.data;
} else if (typeof response?.body === 'string') {
  content = response.body;
} else {
  content = JSON.stringify(response ?? {});
}

const parseInteger = (value, fallback) => {
  const parsed = parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const maxContentChars = source.maxContentChars || 6000;
const originalContentChars = content.length;
const truncatedContent = content.slice(0, maxContentChars);
const currentAttempt = parseInteger(source.retry?.currentAttempt, 1);
const maxAttempts = parseInteger(source.retry?.maxAttempts, 3);

return {
  json: {
    status: 'ok',
    provider: 'jina_reader',
    url: source.url,
    readerUrl: source.readerUrl,
    fetched: true,
    contentType: 'markdown',
    contentChars: truncatedContent.length,
    originalContentChars,
    truncated: originalContentChars > maxContentChars,
    // Preferred key for downstream workflows and AI nodes.
    content: truncatedContent,
    reader: {
      status: 'ok',
      fetched: true,
      provider: 'jina_reader',
      readerUrl: source.readerUrl
    },
    retry: {
      ...(source.retry || {}),
      maxAttempts,
      currentAttempt,
      attemptsMade: currentAttempt,
      remainingAttempts: Math.max(0, maxAttempts - currentAttempt),
      succeeded: true,
      succeededAttempt: currentAttempt,
      failedAttempts: Array.isArray(source.retry?.errors) ? source.retry.errors.length : 0
    },
    rateLimit: source.rateLimit,
    request: source.request,
    metadata: {
      strategy: 'single_url_jina_reader_free_endpoint_with_redis_simple_counter_rate_limit_and_retry',
      contentKey: 'content',
      contentKeyNote: 'Use top-level content as the preferred key for the markdown read from the URL.',
      maxContentChars,
      requestTimeoutMs: source.requestTimeoutMs,
      rateLimitStrategy: source.rateLimit?.strategy,
      retryStrategy: source.retry?.strategy,
      firstFetchCountsAsAttempt: true
    },
    receivedAt: new Date().toISOString()
  }
};

let normalizedSource = {};
let attemptSource = {};
let rateLimitSource = {};
let originalInput = {};

try {
  normalizedSource = $('Normalize Input').first().json || {};
} catch (error) {
  normalizedSource = {};
}

try {
  attemptSource = $('Prepare Attempt State').item.json || {};
} catch (error) {
  attemptSource = {};
}

try {
  rateLimitSource = $('Attach Rate Limit State').item.json || {};
} catch (error) {
  rateLimitSource = {};
}

try {
  originalInput = $('When Executed by Another Workflow').first().json || {};
} catch (error) {
  originalInput = {};
}

const input = $input.item.json || {};
const rawError = input.lastError || input.error || input;

const safeStringify = (value, maxLength = 4000) => {
  try {
    const seen = new WeakSet();
    const text = JSON.stringify(value, (key, val) => {
      if (typeof val === 'object' && val !== null) {
        if (seen.has(val)) return '[Circular]';
        seen.add(val);
      }
      return val;
    });
    return text ? text.slice(0, maxLength) : null;
  } catch (error) {
    return String(value).slice(0, maxLength);
  }
};

const pickString = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return null;
};

const getStatusCode = (value) => {
  if (!value || typeof value !== 'object') return null;
  return value.statusCode || value.status || value.httpCode || value.response?.statusCode || value.response?.status || null;
};

const normalizeError = (value) => ({
  message: pickString(
    value?.message,
    value?.description,
    input.message,
    input.description,
    typeof value === 'string' ? value : null,
  ) || 'Jina Reader workflow failed',
  name: pickString(value?.name, input.name),
  statusCode: getStatusCode(value) || getStatusCode(input),
  code: value?.code || input.code || null,
  description: pickString(value?.description, input.description),
  responseBody: pickString(
    value?.responseBody,
    value?.response?.body,
    value?.response?.data,
    value?.body,
    value?.data,
    input.body,
    input.data,
  ),
  stack: pickString(value?.stack, input.stack),
  rawPreview: value?.rawPreview || safeStringify(value)
});

const bestSource = input.url || input.retry
  ? input
  : (Object.keys(rateLimitSource).length ? rateLimitSource : (Object.keys(attemptSource).length ? attemptSource : normalizedSource));
const attemptedUrl = bestSource.url || originalInput.url || originalInput.targetUrl || originalInput.sourceUrl || originalInput.href || originalInput.link || null;
const attemptedReaderUrl = bestSource.readerUrl || null;
const inputPreview = JSON.stringify({ originalInput, errorInput: input }).slice(0, 1000);
const error = normalizeError(rawError);
const retry = bestSource.retry || input.retry || null;

return {
  json: {
    status: 'error',
    provider: 'jina_reader',
    url: attemptedUrl,
    readerUrl: attemptedReaderUrl,
    fetched: false,
    content: null,
    contentChars: 0,
    originalContentChars: 0,
    truncated: false,
    error,
    retry,
    attemptsMade: retry?.attemptsMade ?? null,
    maxAttempts: retry?.maxAttempts ?? null,
    rateLimit: bestSource.rateLimit || normalizedSource.rateLimit || null,
    request: bestSource.request || normalizedSource.request || {
      input: originalInput
    },
    metadata: {
      strategy: 'single_url_jina_reader_free_endpoint_with_redis_simple_counter_rate_limit_and_retry',
      contentKey: 'content',
      urlHandling: 'string_only_brave_workflow_style',
      retryStrategy: retry?.strategy || 'reader_http_error_retry_total_attempts_first_fetch_is_attempt_1',
      firstFetchCountsAsAttempt: true,
      inputPreview
    },
    receivedAt: new Date().toISOString()
  }
};

const input = $input.item.json || {};
const parseInteger = (value, fallback) => {
  const parsed = parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
};
const maxAttempts = parseInteger(input.retry?.maxAttempts, 3);
const currentAttempt = Math.min(Math.max(parseInteger(input.retry?.currentAttempt, 1), 1), maxAttempts);
const attemptsMade = Math.min(Math.max(parseInteger(input.retry?.attemptsMade, currentAttempt - 1), 0), maxAttempts);
const errors = Array.isArray(input.retry?.errors) ? input.retry.errors : [];

return {
  json: {
    ...input,
    retry: {
      ...(input.retry || {}),
      enabled: maxAttempts > 1,
      provider: 'workflow_loop',
      strategy: 'reader_http_error_retry_total_attempts_first_fetch_is_attempt_1',
      maxAttempts,
      currentAttempt,
      attemptsMade,
      remainingAttempts: Math.max(0, maxAttempts - currentAttempt),
      errors,
      attemptStartedAt: new Date().toISOString()
    }
  }
};

let source = {};
try {
  source = $('Attach Rate Limit State').item.json || {};
} catch (error) {
  try {
    source = $('Prepare Attempt State').item.json || {};
  } catch (innerError) {
    source = {};
  }
}

const input = $input.item.json || {};
const rawError = input.error ?? input;

const safeStringify = (value, maxLength = 4000) => {
  try {
    const seen = new WeakSet();
    const text = JSON.stringify(value, (key, val) => {
      if (typeof val === 'object' && val !== null) {
        if (seen.has(val)) return '[Circular]';
        seen.add(val);
      }
      return val;
    });
    return text ? text.slice(0, maxLength) : null;
  } catch (error) {
    return String(value).slice(0, maxLength);
  }
};

const pickString = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return null;
};

const getStatusCode = (value) => {
  if (!value || typeof value !== 'object') return null;
  return value.statusCode || value.status || value.httpCode || value.response?.statusCode || value.response?.status || null;
};

const errorDetails = {
  message: pickString(
    rawError?.message,
    rawError?.description,
    input.message,
    input.description,
    typeof rawError === 'string' ? rawError : null,
  ) || 'Jina Reader request failed',
  name: pickString(rawError?.name, input.name),
  statusCode: getStatusCode(rawError) || getStatusCode(input),
  code: rawError?.code || input.code || null,
  description: pickString(rawError?.description, input.description),
  responseBody: pickString(
    rawError?.response?.body,
    rawError?.response?.data,
    rawError?.body,
    rawError?.data,
    input.body,
    input.data,
  ),
  stack: pickString(rawError?.stack, input.stack),
  rawPreview: safeStringify(rawError)
};

const parseInteger = (value, fallback) => {
  const parsed = parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const maxAttempts = parseInteger(source.retry?.maxAttempts, 3);
const currentAttempt = parseInteger(source.retry?.currentAttempt, 1);
const previousErrors = Array.isArray(source.retry?.errors) ? source.retry.errors : [];
const attemptError = {
  attempt: currentAttempt,
  failedAt: new Date().toISOString(),
  readerUrl: source.readerUrl || null,
  ...errorDetails
};
const errors = [...previousErrors, attemptError];
const shouldRetry = currentAttempt < maxAttempts;

return {
  json: {
    ...source,
    fetched: false,
    lastError: errorDetails,
    shouldRetry,
    retry: {
      ...(source.retry || {}),
      maxAttempts,
      currentAttempt: shouldRetry ? currentAttempt + 1 : currentAttempt,
      attemptsMade: currentAttempt,
      remainingAttempts: shouldRetry ? Math.max(0, maxAttempts - (currentAttempt + 1)) : 0,
      lastFailedAttempt: currentAttempt,
      nextAttempt: shouldRetry ? currentAttempt + 1 : null,
      shouldRetry,
      errors
    },
    error: errorDetails,
    metadata: {
      ...(source.metadata || {}),
      retryDecisionAt: new Date().toISOString(),
      retryStrategy: source.retry?.strategy || 'reader_http_error_retry_total_attempts_first_fetch_is_attempt_1'
    }
  }
};
